import math, pandas as pd, numpy as np

# Reuse staged results only; create new health-interpretation variables without overwriting prior work.
def _safe_scalar(x):
    try:
        if pd.isna(x): return None
    except Exception:
        pass
    if isinstance(x, (np.generic,)): return x.item()
    return x

def _to_plain(obj):
    if isinstance(obj, dict):
        return {str(k): _to_plain(v) for k, v in obj.items()}
    if isinstance(obj, pd.Series):
        return {str(k): _to_plain(v) for k, v in obj.to_dict().items()}
    if isinstance(obj, pd.DataFrame):
        return obj.head(10).to_dict("records")
    if isinstance(obj, (list, tuple)):
        return [_to_plain(v) for v in obj]
    return _safe_scalar(obj)

